research_meta_tool:
"""Generated LEGIT-017 cross-domain test-witness cache.
No network, file writing or deployment rights. Research only.
"""
NO_EXTERNAL_ACTIONS = True
def build(records):
    table={}
    for key,answer in records:
        if key in table:
            raise ValueError("Duplicate independent test witness")
        table[key]=answer
    return table
def answer(table,key):
    return table[key]

selected_tools.GRAPH:
"""LEGIT-017 bounded generated graph reachability tool; research only."""
NO_EXTERNAL_ACTIONS = True
def build(instance):
    n,edges=instance
    adjacency=[[] for _ in range(n)]
    for source,target in edges:
        adjacency[source].append(target)
    all_reached=[]
    for start in range(n):
        pending=[start]
        visited={start}
        while pending:
            vertex=pending.pop()
            for nxt in adjacency[vertex]:
                if nxt not in visited:
                    visited.add(nxt)
                    pending.append(nxt)
        all_reached.append(frozenset(visited))
    return tuple(all_reached)
def answer(context,query):
    source,target=query
    return target in context[source]

selected_tools.SUBSET:
"""LEGIT-017 bounded generated subset-sum feasibility tool; research only."""
NO_EXTERNAL_ACTIONS = True
def build(weights):
    possible=1
    for value in weights:
        possible|=possible<<value
    return possible
def answer(context,target):
    return target>=0 and ((context>>target)&1)==1
